#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m, s;
    cin >> n >> m >> s;
    vector<vector<pair<int, int>>> graph(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        graph[u].push_back({v, w});      // 방향 간선 u -> v (가중치 w)
    }

    const long long INF = 1e18;
    vector<long long> dist(n + 1, INF);
    // greater<> 를 넣어야 최소 힙이 돼요 (기본은 최대 힙)
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    dist[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;       // 이미 더 짧은 거리로 처리한 정점
        for (auto [v, w] : graph[u]) {
            long long nd = d + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                pq.push({nd, v});
            }
        }
    }

    for (int v = 1; v <= n; v++) {
        cout << (dist[v] == INF ? -1 : dist[v]) << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n = 5;
    vector<array<int, 3>> edges = {{1, 2, 0}, {1, 3, 1}, {2, 3, 1}, {2, 4, 1}, {3, 5, 0}, {4, 5, 0}};
    vector<vector<pair<int, int>>> graph(n + 1);
    for (auto [u, v, w] : edges) {       // 양방향 간선, 가중치는 0 또는 1
        graph[u].push_back({v, w});
        graph[v].push_back({u, w});
    }

    const int INF = INT_MAX;
    vector<int> dist(n + 1, INF);
    deque<int> dq;
    dist[1] = 0;
    dq.push_back(1);
    while (!dq.empty()) {
        int u = dq.front();
        dq.pop_front();
        for (auto [v, w] : graph[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                if (w == 0) dq.push_front(v);   // 비용 0: 앞에 넣어 먼저 처리
                else dq.push_back(v);           // 비용 1: 뒤에 넣기
            }
        }
    }
    for (int v = 1; v <= n; v++) cout << dist[v] << (v == n ? '\n' : ' ');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    const long long INF = 1e18;          // INF + INF 도 long long 범위 안이에요
    int n = 4;
    vector<vector<long long>> d(n, vector<long long>(n, INF));
    for (int i = 0; i < n; i++) d[i][i] = 0;
    vector<array<int, 3>> edges = {{0, 1, 5}, {0, 2, 9}, {1, 2, 2}, {2, 3, 1}, {3, 1, 4}};
    for (auto [u, v, w] : edges) d[u][v] = min(d[u][v], (long long)w);

    for (int k = 0; k < n; k++)          // 거쳐 가는 정점 k 가 가장 바깥
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (d[i][k] < INF && d[k][j] < INF)
                    d[i][j] = min(d[i][j], d[i][k] + d[k][j]);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j) cout << ' ';
            if (d[i][j] == INF) cout << "INF";
            else cout << d[i][j];
        }
        cout << '\n';
    }
    return 0;
}

